internal class GUPPriceEngineAttributeGroupPriorityCache
{
    Map priceComponentByUniqueKey = null;
    Map priceComponentCodeMap = null;


}

Method.Source:
    public void doRefresh()
    {
        // Key = GUPPriceComponentCodePriceAttributeGroupCombination.parmUniqueKey().
        // Value = Priority (Int64).
        priceComponentByUniqueKey = new Map(Types::String, Types::Int64);

        // Key = PriceComponent (Enum), Value = GUPPriceComponentCode (int64).
        // Only valid for GUPPriceComponent with unique component code (e.g. TradeAgreement).
        priceComponentCodeMap = new Map(Types::Enum, Types::Int64);

        GUPPriceComponentCode gupPriceComponentCode;
        GUPPriceComponentCodePriceAttributeGroupCombination gupPriceComponentCodePriceAttributeGroupCombination;
        while select * from gupPriceComponentCode
            join gupPriceComponentCodePriceAttributeGroupCombination
            where gupPriceComponentCode.RecId == gupPriceComponentCodePriceAttributeGroupCombination.PriceComponentCode
        {
            GUPPriceComponent priceComponent = gupPriceComponentCode.PriceComponent;
            priceComponentByUniqueKey.add(gupPriceComponentCodePriceAttributeGroupCombination.parmUniqueKey(), 
                gupPriceComponentCodePriceAttributeGroupCombination.Priority);

            priceComponentCodeMap.add(gupPriceComponentCode.PriceComponent, gupPriceComponentCodePriceAttributeGroupCombination.PriceComponentCode);
        }

    }

public int64 getPriority(int64 _headerAttributeGroup,
    int64 _lineAttributeGroup,  
    int64 _priceComponentCode)
{
    str key = GUPPriceComponentCodePriceAttributeGroupCombination::generateUniqueKey(_priceComponentCode, _headerAttributeGroup, _lineAttributeGroup);
    return priceComponentByUniqueKey.lookup(key);
}
